def next_smallest_palindrome(n):
    # Convert the number to a string to easily manipulate digits
    num_str = str(n)

    # Check if the number is already a palindrome
    if num_str == num_str[::-1]:
        return n

    # Find the first digit that needs to be moved to make it a palindrome
    for i in range(len(num_str)):
        if int(num_str[i]) > int(num_str[-i-1]):
            break

    # Move the first digit to the end of the string
    num_str = num_str[:i] + num_str[i+1:]

    # Convert back to integer and check if it's a palindrome
    return int(''.join(sorted(str(num_str)))[::-1])
