def is_abundant(n):
    # Calculate the sum of all divisors of n
    total_sum = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            total_sum += i
            if i != n // i:
                total_sum += n // i

    # Check if the sum of divisors equals the original number
    return total_sum == n
