def previous_palindrome(n):
    # Convert the number to a string for easier manipulation
    num_str = str(n)

    # Check if the number is already a palindrome
    if num_str == num_str[::-1]:
        return n

    # Find the first non-palindromic character from the right
    for i in range(len(num_str) - 1, -1, -1):
        if num_str[i] != num_str[-i-1]:
            break
    else:
        # If no non-palindromic characters found, reverse the entire string
        return int(''.join(reversed(num_str)))

