    freq = {}

    # Populate the dictionary with frequencies
    for num in arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Initialize the sum to zero
    total_sum = 0

    # Iterate through the dictionary to calculate the sum of non-repeated elements
    for num, count in freq.items():
        if count > 1:
            total_sum += (target - num)

