def is_Isomorphic(str1, str2):
    # Create dictionaries for both strings
    dict1 = {}
    dict2 = {}

    # Iterate through characters of first string
    for i in range(len(str1)):
        # Check if character exists in dictionary
        if str1[i] in dict1:
            # If it does, return False as they are not isomorphic
            if dict1[str1[i]] != str2[i]:
                return False
        else:
            # Add character to dictionary
            dict1[str1[i]] = str2[i]

        # Check if character exists in dictionary again
        if str2[i] in dict2:
            # If it does, return False as they are not isomorphic
            if dict2[str2[i]] != str1[i]:
                return False
        else:
            # Add character to dictionary
            dict2[str2[i]] = str1[i]

    # If no mismatches were found, return True
    return True
