def find_closet(arr1, arr2, arr3, n, m, k):
    # Initialize pointers for each array
    i = j = k = 0

    # Find the first element that appears in all three arrays
    while i < len(arr1) and j < len(arr2) and k < len(arr3):
        if arr1[i] == arr2[j] == arr3[k]:
            return min(arr1[i], arr2[j], arr3[k])

        # Move pointer based on which array has the smallest difference
        if arr1[i] < arr2[j]:
            i += 1
        elif arr1[i] > arr2[j]:
            j += 1
        else:
            k += 1

    # If no common element found, return None
    return None

