def unique_sublists(lst):
    # Create a dictionary to store the sets of sublists
    result = {}

    for sublist in lst:
        # Convert each sublist into a set to remove duplicates
        new_set = set(sublist)

        # Check if the new set has already been seen
        if new_set not in result:
            result[new_set] = 1
        else:
            result[new_set] += 1

    return result

