def move_zeroes(nums):
    # Iterate through the list from right to left
    for i in range(len(nums) - 1, -1, -1):
        # If the current element is zero, skip it
        if nums[i] == 0:
            continue
        # Move the zero to the front of the list
        while i < len(nums) - 1 and nums[i + 1] != 0:
            nums[i], nums[i + 1] = nums[i + 1], nums[i]
            i += 1
    return nums
