    if len(arr) <= 1:
        return True

    # Check if the root value is less than or equal to its children's values
    for i in range(len(arr)):
        if arr[i] > arr[2 * i + 1]:
            return False

    # Recursively check the left and right subtrees
    return check_min_heap(arr[:len(arr)//2]) and check_min_heap(arr[len(arr)//2+1:])
