def maximum_segments(n, a, b, c):
    # Calculate the minimum value among a, b, and c
    min_value = min(a, b, c)

    # If any of the values is less than or equal to the minimum, return 0
    if min_value <= n:
        return 0

    # Initialize the count of segments
    count = 0

    # Iterate through all possible combinations of segments
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            for k in range(j + 1, n + 1):
                # Check if the current combination forms a valid segment
                if (i * a + j * b + k * c) % (min_value * 3) == 0:
                    count += 1

    return count
