    dp[0] = 1
    for i in range(1, len(dp)):
        if nums[i - 1] != 0:
            dp[i] += dp[i-1]

    ret = float("inf")
    for i in range(len(nums), -1, -1):
        tmp = []
        for j in range(k+1):
            if i <= len(nums)-j < len(tmp):
                tmp.append(nums[j])

