                    elif j < len(nums)-1 and nums[j] != nums[j+1] and nums[j] != nums[i-1] and nums[j] != nums[i+1]:
                        break
                    else:
                        found = True
                        break

                if found:
                    visited.add(i)
                    find_combinations(sums, combination+[nums[i]], i+1, path+[nums[i]], visited)
                    visited.remove(i)

    start_index = 0
    end_index = len(nums)
    sums = [num for num in nums]
    path = []

    while start_index < end_index:
        mid_index = (start_index + end_index)//2
        find_combinations(sums, [], 0, [], set())

