def min_Num(nums, target_sum):
    # Calculate the minimum difference between consecutive elements in nums
    difference = max(abs(nums[i] - nums[i-1]) for i in range(len(nums)-1)) + abs(target_sum - nums[-1])

    # If the calculated difference is greater than the maximum possible difference (max(nums)), return None
    if difference > max(nums):
