def get_Pairs_Count(arr, target_sum, n):
    # Initialize result counter
    count = 0

    # Sort the array
    arr.sort()

    # Iterate through the array to find all valid pairs
    for i in range(n-1):
        if arr[i] > (target_sum - arr[i]):
            break
        j = i + 1
        k = n - 1

        while j < k:
            current_sum = arr[i] + arr[j] + arr[k]

            # If current sum equals target_sum, increment count
            if current_sum == target_sum:
                count += 1
                # Skip duplicates by skipping the same element
                while j < k and arr[j] == arr[j+1]:
                    j += 1
                while j < k and arr[k] == arr[k-1]:
                    k -= 1
            elif current_sum < target_sum:
                j += 1
            else:
                k -= 1

    return count
