def get_Pairs_Count(l, sum, k):
    count = 0
    l.sort()

    for i in range(len(l)):
        left = i + 1
        right = len(l) - 1

        while left < right:
            current_sum = l[i] + l[left] + l[right]

            if current_sum == sum:
                count += 1
                left += 1
                right -= 1

            elif current_sum < sum:
                left += 1
            else:
                right -= 1

    return count
