def min_Jumps(x, y, d):
    if x > d:
        return float('inf')

    # Initialize variables to track the maximum distance covered so far and the minimum number of jumps needed
    max_distance = 0
    jump_count = 0

    # Traverse through all possible steps
    while max_distance < y - d + 1:
        max_distance += 1
        jump_count += 1

    return min(jump_count, max_distance)
