                characters_before_first_parens.append(char)
        elif char == ')':
            index = characters_before_first_parens.index(current_char)
            del characters_before_first_parens[index]
            if index - 2 >= 0:
                characters_before_first_parens.insert(index - 2, '(')
            characters_before_first_parens.append(')')

    return ''.join(characters_before_first_parens)

