def check_min_heap(arr):
    # Helper function to check if the subtree rooted at index i is a valid min heap
    def is_min_heap(arr, i):
        left_child = 2 * i + 1
        right_child = 2 * i + 2
        smallest = i

        if left_child < len(arr) and arr[left_child] < arr[smallest]:
            smallest = left_child

        if right_child < len(arr) and arr[right_child] < arr[smallest]:
            smallest = right_child

        if smallest != i:
            arr[i], arr[smallest] = arr[smallest], arr[i]
            return is_min_heap(arr, smallest)

        return True

    # Check if all elements in the heap satisfy the min heap property
    for i in range(len(arr)):
        if not is_min_heap(arr, i):
            return False

    return True
