def super_seq(str1, str2, n, m):
    # Check if str1 is equal to str2
    if str1 == str2:
        return min(len(str1), len(str2))

    # Initialize results for subsequence lengths
    res1 = min(len(str1), m)
    res2 = min(len(str2), n)

    # If one of the strings is empty or longer than the other, return the shorter one
    if not str1 or n < 0 or (not str2 and m < 0) or (str1 and n > 0 and str2 and m > 0):
        return max(res1, res2)

    # Iterate through characters of str1 and str2 simultaneously
    while n >= 0 and m >= 0:
        if str1[n] != str2[m]:
            break
        n -= 1
        m -= 1

    # If we have reached the end of either string, return its length
    if n < 0 or m < 0:
        return min(res1, res2)

    # Calculate the minimum length by combining substrings
    return res1 + res2 - max(0, n) - max(0, m)

