    min1 = min2 = nums[0]
    max1 = max2 = nums[0]

    for num in nums:
        # Update max1 and min1 or max2 and min2 based on which is larger
        if num > max1 + max2:
            max2 = max1
            max1 = num
        elif num >= max1 + max2:
            max2 = num

        # Update max1 and min1 or max2 and min2 based on which is smaller
        if num < min1 + min2:
            min2 = min1
            min1 = num
