def rgb_to_hsv(r, g, b):
    # Convert RGB values to HSV values
    max_color = max(r, g, b)
    min_color = min(r, g, b)
    delta = max_color - min_color

    if max_color == min_color:
        hue = 0
    elif delta == 0:
        hue = 0
    else:
        hue = (1 + (2 * delta) / (max_color + min_color)) % 6

    saturation = 0
    if max_color == r:
        saturation = (g - b) / float(max_color)
    elif max_color == g:
        saturation = (b - r) / float(max_color)
    elif max_color == b:
        saturation = (r - g) / float(max_color)

    # Normalize hue between 0 and 360 degrees
    if hue > 360:
        hue -= 360
    if hue < 0:
        hue += 360

    return int(hue), int(saturation), int((1 - saturation) * 255)

