    dp = [arr[0]] * (n + 1)  # Initialize DP table

    for i in range(1, n+1):
        current_max = arr[i-1]

        for j in range(i-1, -1, -1):
            if j == 0:
                dp[j] = arr[j]
            elif j > 0:
                dp[j] = max(dp[j], dp[j-1] + arr[j])

            if dp[j] >= current_max:
                current_max = dp[j]

        dp[i] = current_max

    return dp[n]

