def lcs_of_three(str1, str2, str3, max_len, min_l, diff):
    if len(str1) < max_len or len(str2) < max_len or len(str3) < max_len:
        return 0

    if str1[0] != str2[0] or str1[0] != str3[0]:
        return 0

    # Check if the first character of all strings matches
    if str1[0] != str2[0] or str1[0] != str3[0]:
        return 0

    # If all characters match at the start of the sequences, calculate LCS length
    if (str1[0] == str2[0] and str1[0] == str3[0]) or \
       (str1[0] == str2[0] and str2[0] == str3[0]):
        return 1 + lcs_of_three(str1[1:], str2[1:], str3[1:], max_len, min_l-1, diff)

    # If any substring has a difference greater than 'diff' then return 0
    if abs(diff) > min_l:
        return 0

    # Otherwise continue searching for longer LCS
    return max(lcs_of_three(str1, str2, str3[1:], max_len, min_l, diff), lcs_of_three(str1[1:], str2[1:], str3[1:], max_len, min_l+1, diff))
```

This solution uses dynamic programming to build up the LCS table by comparing each pair of strings starting from their first characters. It keeps track of the maximum length of LCS found so far and returns this value when it's larger than the previous maximum.

