    for i in range(n-2):
        for j in range(i+1, n-1):
            k = j + 1
            l = n

            while k < l:
                current_sum = arr[i] + arr[j] + arr[k] + arr[l]

                if current_sum == target_sum:
                    return (arr[i], arr[j], arr[k])

                elif current_sum > target_sum:
                    l -= 1

