def find_triplet(arr, target_sum):
    n = len(arr)
    for i in range(n-2):  # Number of triplets we need to check
        left, right = i+1, n-1  # Initialize two pointers

        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]

