            max_platforms_per_stop = len(current_min_platforms)

        stop_index = 0

        for i in range(total_stops - 1):
            if stops[stop_index] + (i + 1) * max_platforms_per_stop < sorted_platforms[i]:
                stop_index += 1

        return max_platforms_per_stop - stop_index + 1
```

