    if len(matrix) < 2 or len(matrix[0]) < 2:
        return None

    total_sum = sum([sum(row) for row in matrix])
    if k >= len(matrix):
        return total_sum / (len(matrix)**2)

    current_sum = [0] * len(matrix)
    for i in range(k):
        current_sum[i] = sum([matrix[j][i] for j in range(len(matrix))])

    best_avg = float('inf')

    for l in range(2, min(len(matrix), k) + 1):
        for i in range(min(l - 1, k - 1)):
            current_sum[i] += current_sum[l - 1]

        best_avg = min(best_avg, maxAverage(current_sum[l:], matrix))

    return best_avg

