def find_longest_conseq_subseq(arr, n):
    # Initialize variables to track the current max length found and the start index
    curr_max = res = -1

    for i in range(n):
        if arr[i] != arr[i+1]:
            # If current element is not equal to next element, reset the current max length
            if curr_max != -1:
                res = max(res, curr_max)
                curr_max = -1

        # Update the previous element's position if it matches the current element
        if arr[i] == arr[i-1]:
            res = max(res, i + 1)

    # Check the last sequence or handle edge cases
    return max(curr_max, n - (res == -1))
