def max_chain_length(pairs_list, k):
    # Sort each pair by its value in ascending order
    for i in range(len(pairs_list)):
        for j in range(i + 1, len(pairs_list)):
            if pairs_list[i].val > pairs_list[j].val:
                pairs_list[i], pairs_list[j] = pairs_list[j], pairs_list[i]

    # Initialize result list
    res = []

    # Iterate through all pairs in reverse order
    for i in range(k - 1, -1, -1):
        found = False

        # Check each pair against previous longest chain
        for j in range(k):
            if pairs_list[k - j - 1].val <= pairs_list[i].val:
                if not found:
                    res.append((pairs_list[i].val, i))
                    found = True
                else:
                    res.append((pairs_list[i].val, i))

        # Remove duplicates from chain length
        while (len(res) >= 2 and res[-2][1] == res[-1][1]) or (len(res) >= 2 and res[-2][1] != res[-1][1]):
            del res[-1]

    return res

