def min_jumps(arr):
    n = len(arr)
    dp = [float('inf')] * n
    dp[0] = 0

    for i in range(n-1):
        for j in range(i+1):
            if (j + arr[i]) < n:
                dp[j+arr[i]] = min(dp[j+arr[i]], dp[i]+1)

    return dp[-1]
```

