def generate_matrix(n):
    # Initialize a list to hold the result matrix
    result = []

    # Function to rotate matrix by one position clockwise
    def rotate(matrix):
        rows, cols = len(matrix), len(matrix[0])
        for r in range(rows):
            for c in range(r + 1, cols):
                matrix[r][c], matrix[c][r] = matrix[c][r], matrix[r][c]

    # Main spiral loop
    while len(result) < n:
        # First row of spiral
        for i in range(n):
            result.append([1])

        # Middle part of the spiral
        for j in range(len(result) - 1)[::-1]:
            if not (j == 0 or (len(result) - j) % 2 == 1):
                result[j].append(j + 2)

        # Last row of spiral
        if len(result) > 0:
            for i in range(len(result) - 1):
                result[-1].append(-1)

        # Top row of spiral
        if len(result) > 0:
            for i in range(len(result) - 1):
                result[i].append((n - i - 1) // 2)

        # Bottom row of spiral
        if len(result) > 0:
            result[len(result) - 1].append((n - len(result)) // 2)

        # Rotate back to original state
        rotate(result)

    return result
```

This solution generates a square matrix filled with numbers from 1 to `n` raised to the power of 2 in spiral order as described in the problem statement. It uses two nested loops to fill the first and last layers of the spiral matrix, and rotates the rest of the layer(s) to align with the top/bottom layers. The main spiral loop ensures that all necessary elements from each level of the spiral are included in the final matrix.

```python
def generate_matrix(n):
    # Generate a list of squares from 1 to n^2
    squares = [i**2 for i in range(1, n+1)]

    result = []
    # Use two pointers approach to achieve spiral order
    left, right, top, bottom = 0, len(squares) - 1, 0, len(result) - 1

    while left <= right and top <= bottom:
        if left <= right:
            for i in range(left, right + 1):
                result.append(squares[top][i])
            top += 1

        if top <= bottom:
            for i in range(top, bottom + 1):
                result.append(squares[i][right])
            right -= 1

        if left <= right:
            for i in range(right, left - 1, -1):
                result.append(squares[bottom][i])
            bottom -= 1

        if top <= bottom:
            for i in range(bottom, top - 1, -1):
                result.append(squares[i][left])
            left += 1

    return result

